//! Writes the deterministic GLB and SVG assets: `gen-assets [out_dir]` (default `assets`).
//! `gen-assets --check [out_dir]` exits non-zero when a file differs from the generated bytes.

use std::path::PathBuf;
use std::{env, fs, process};

fn main() {
    let mut args: Vec<String> = env::args().skip(1).collect();
    let check = args.first().is_some_and(|a| a == "--check");
    if check {
        args.remove(0);
    }
    let out = PathBuf::from(args.first().map_or("assets", String::as_str));
    let mut stale = false;
    for (rel, bytes) in game::procgen::all_assets() {
        let path = out.join(rel);
        if check {
            if fs::read(&path).ok().as_deref() != Some(bytes.as_slice()) {
                eprintln!("stale: {}", path.display());
                stale = true;
            }
            continue;
        }
        if let Some(dir) = path.parent() {
            fs::create_dir_all(dir).expect("create asset directory");
        }
        fs::write(&path, &bytes).expect("write asset");
        println!("{} ({} bytes)", path.display(), bytes.len());
    }
    if stale {
        process::exit(1);
    }
}
